const solicitud = $input.first().json;

// Solo enviamos al subworkflow el encabezado que necesita.
return [{
  json: {
    headers: {
      authorization:
        typeof solicitud.headers?.authorization === 'string'
          ? solicitud.headers.authorization
          : '',
    },
  },
}];

const autenticacion = $input.first().json;

// Comprobamos el contrato de respuesta del subworkflow.
if (![200, 401, 503].includes(autenticacion.status_http)) {
  throw new Error('Respuesta de autenticación inesperada.');
}

// Una sesión rechazada no debe generar códigos.
if (autenticacion.status_http !== 200) {
  return [{
    json: {
      generar: false,
      status_http: autenticacion.status_http,
      respuesta: autenticacion.respuesta,
    },
  }];
}

const usuario = autenticacion.respuesta?.data?.usuario;

if (
  autenticacion.respuesta?.ok !== true ||
  typeof usuario?.usuario_id !== 'string' ||
  !usuario.usuario_id.trim()
) {
  throw new Error('La autenticación no devolvió un usuario válido.');
}

// El cliente debe enviar únicamente un objeto JSON vacío.
const solicitud =
  $('Webhook - Solicitar código Telegram').first().json;

const contentType = String(
  solicitud.headers?.['content-type'] ?? ''
)
  .split(';')[0]
  .trim()
  .toLowerCase();

const cuerpo = solicitud.body;

const cuerpoValido =
  cuerpo !== null &&
  typeof cuerpo === 'object' &&
  !Array.isArray(cuerpo) &&
  Object.keys(cuerpo).length === 0;

if (contentType !== 'application/json' || !cuerpoValido) {
  return [{
    json: {
      generar: false,
      status_http: contentType !== 'application/json' ? 415 : 400,
      respuesta: {
        ok: false,
        error: {
          codigo: 'SOLICITUD_INVALIDA',
          mensaje: 'Envía un objeto JSON vacío: {}.',
        },
      },
    },
  }];
}

