const actualizacion = $input.first().json;
const mensaje = actualizacion.message;

// Solo procesamos mensajes de personas en su chat privado.
// Ignoramos grupos, canales y mensajes enviados por bots.
const chatPrivadoValido =
  mensaje?.chat?.type === 'private' &&
  mensaje?.from?.is_bot === false &&
  Number.isSafeInteger(mensaje.chat.id) &&
  Number.isSafeInteger(mensaje.from.id) &&
  mensaje.chat.id > 0 &&
  mensaje.chat.id === mensaje.from.id;

if (!chatPrivadoValido) {
  return [{
    json: {
      procesar: false,
      responder: false,
      motivo: 'CHAT_NO_ADMITIDO',
    },
  }];
}

const chatId = String(mensaje.chat.id);
const texto =
  typeof mensaje.text === 'string'
    ? mensaje.text.trim()
    : '';

// Exigimos el formato exacto que genera nuestro endpoint.
const coincidencia = /^\/vincular ([a-f0-9]{32})$/.exec(texto);

if (!coincidencia) {
  return [{
    json: {
      procesar: false,
      responder: true,
      chat_id: chatId,
      motivo: 'COMANDO_INVALIDO',
      mensaje:
        'Solicita un código en EventPass y envía /vincular seguido del código.',
    },
  }];
}

const { createHash } = require('crypto');

// Buscamos por la huella, sin propagar el código original.
const huella = createHash('sha256')
  .update(coincidencia[1], 'utf8')
  .digest('hex');

return [{
  json: {
    procesar: true,
    responder: true,
    chat_id: chatId,
    telegram_username:
      typeof mensaje.from.username === 'string'
        ? mensaje.from.username
        : '',
    codigo_hash: `sha256:${huella}`,
  },
}];

const comando =
  $('Interpretar comando de vinculación').first().json;

const filas = $input.all()
  .map(item => item.json)
  .filter(fila => Object.keys(fila).length > 0);

// Un mismo código no debería identificar varios registros.
if (filas.length > 1) {
  throw new Error('Se encontraron registros duplicados del código.');
}

const codigo = filas[0];

function rechazar() {
  // Usamos la misma respuesta para inexistentes, vencidos y usados.
  return [{
    json: {
      codigo_valido: false,
      chat_id: comando.chat_id,
      mensaje:
        'El código no es válido o ya venció. Solicita uno nuevo en EventPass.',
    },
  }];
}

if (!codigo) {
  return rechazar();
}

// Validamos la integridad del registro antes de utilizarlo.
if (
  typeof codigo.codigo_id !== 'string' ||
  !codigo.codigo_id.trim() ||
  typeof codigo.usuario_id !== 'string' ||
  !codigo.usuario_id.trim() ||
  codigo.codigo !== comando.codigo_hash
) {
  throw new Error('El registro del código está incompleto o es inconsistente.');
}

const estadosPermitidos = [
  'PENDIENTE',
  'USADO',
  'EXPIRADO',
  'CANCELADO',
];

if (!estadosPermitidos.includes(codigo.estado)) {
  throw new Error('El código tiene un estado desconocido.');
}

const creadoEn = Date.parse(codigo.creado_en);
const expiraEn = Date.parse(codigo.expira_en);
const ahora = Date.now();

if (
  !Number.isFinite(creadoEn) ||
  !Number.isFinite(expiraEn) ||
  expiraEn <= creadoEn ||
  expiraEn - creadoEn > 10 * 60 * 1000
) {
  throw new Error('Las fechas del código son inconsistentes.');
}

const usadoEn = String(codigo.usado_en ?? '').trim();

if (
  codigo.estado !== 'PENDIENTE' ||
  usadoEn !== '' ||
  creadoEn > ahora ||
  expiraEn <= ahora
) {
  return rechazar();
}

return [{
  json: {
    codigo_valido: true,
    codigo_id: codigo.codigo_id,
    usuario_id: codigo.usuario_id,
    chat_id: comando.chat_id,
    telegram_username: comando.telegram_username,
    expira_en: codigo.expira_en,
  },
}];

const contexto =
  $('Comprobar código de vinculación').first().json;

if (contexto.codigo_valido !== true) {
  throw new Error('Se recibió un código no validado.');
}

const usuarios = $input.all()
  .map(item => item.json)
  .filter(fila => Object.keys(fila).length > 0);

if (usuarios.length > 1) {
  throw new Error('Hay usuarios duplicados con el mismo identificador.');
}

const usuario = usuarios[0];

if (
  usuario &&
  usuario.usuario_id !== contexto.usuario_id
) {
  throw new Error('El usuario encontrado no coincide con el código.');
}

if (
  usuario &&
  !['ACTIVO', 'INACTIVO'].includes(usuario.estado)
) {
  throw new Error('El usuario tiene un estado desconocido.');
}

// Volvemos a comprobar el vencimiento porque ya pasó
// tiempo desde la primera consulta.
const vencimiento = Date.parse(contexto.expira_en);

if (!Number.isFinite(vencimiento)) {
  throw new Error('El vencimiento del código no es válido.');
}

const permitido =
  Boolean(usuario) &&
  usuario.estado === 'ACTIVO' &&
  vencimiento > Date.now();

if (!permitido) {
  return [{
    json: {
      usuario_vinculable: false,
      chat_id: contexto.chat_id,
      mensaje:
        'No es posible vincular la cuenta. Comprueba que esté activa y solicita un código nuevo.',
    },
  }];
}

// No propagamos el hash de contraseña ni otros datos del usuario.
return [{
  json: {
    usuario_vinculable: true,
    codigo_id: contexto.codigo_id,
    usuario_id: contexto.usuario_id,
    chat_id: contexto.chat_id,
    telegram_username: contexto.telegram_username,
    expira_en: contexto.expira_en,
  },
}];

const contexto =
  $('Validar usuario para vinculación').first().json;

if (contexto.usuario_vinculable !== true) {
  throw new Error('El usuario no está autorizado para vincularse.');
}

const filas = $input.all()
  .map(item => item.json)
  .filter(fila => Object.keys(fila).length > 0);

function texto(valor) {
  return String(valor ?? '').trim();
}

// Comprobamos que los registros existentes sean interpretables.
const ids = new Set();

for (const fila of filas) {
  const id = texto(fila.vinculacion_id);

  if (
    !id ||
    !texto(fila.usuario_id) ||
    !/^[1-9]\d*$/.test(texto(fila.chat_id)) ||
    !['ACTIVA', 'INACTIVA'].includes(fila.estado)
  ) {
    throw new Error('Hay una vinculación con datos inconsistentes.');
  }

  if (ids.has(id)) {
    throw new Error('Hay identificadores de vinculación duplicados.');
  }

  ids.add(id);
}

const activas = filas.filter(fila => fila.estado === 'ACTIVA');

const delUsuario = activas.filter(
  fila => texto(fila.usuario_id) === contexto.usuario_id
);

const delChat = activas.filter(
  fila => texto(fila.chat_id) === contexto.chat_id
);

// Si la hoja ya viola la unicidad, detenemos la operación.
if (delUsuario.length > 1 || delChat.length > 1) {
  throw new Error('Hay varias vinculaciones activas para el usuario o chat.');
}

const base = {
  codigo_id: contexto.codigo_id,
  usuario_id: contexto.usuario_id,
  chat_id: contexto.chat_id,
  telegram_username: contexto.telegram_username,
  expira_en: contexto.expira_en,
};

// Revalidamos el tiempo antes de preparar cualquier escritura.
const vencimiento = Date.parse(contexto.expira_en);

if (!Number.isFinite(vencimiento)) {
  throw new Error('El vencimiento del código no es válido.');
}

if (vencimiento <= Date.now()) {
  return [{
    json: {
      ...base,
      resultado: 'RECHAZADO',
      crear_vinculacion: false,
      mensaje: 'El código venció. Solicita uno nuevo en EventPass.',
    },
  }];
}

const mismaRelacion =
  delUsuario.length === 1 &&
  texto(delUsuario[0].chat_id) === contexto.chat_id;

if (mismaRelacion) {
  return [{
    json: {
      ...base,
      resultado: 'YA_VINCULADO',
      crear_vinculacion: false,
      vinculacion_id: texto(delUsuario[0].vinculacion_id),
      mensaje: 'Tu cuenta ya está vinculada a este chat.',
    },
  }];
}

if (delUsuario.length > 0 || delChat.length > 0) {
  return [{
    json: {
      ...base,
      resultado: 'CONFLICTO',
      crear_vinculacion: false,
      mensaje:
        'No se puede crear la vinculación porque la cuenta o el chat ya tiene otra vinculación activa.',
    },
  }];
}

return [{
  json: {
    ...base,
    resultado: 'PERMITIDO',
    crear_vinculacion: true,
  },
}];

const datos = $input.first().json;

const resultados = [
  'PERMITIDO',
  'YA_VINCULADO',
  'CONFLICTO',
  'RECHAZADO',
];

if (!resultados.includes(datos.resultado)) {
  throw new Error('Resultado de vinculación desconocido.');
}

if (['CONFLICTO', 'RECHAZADO'].includes(datos.resultado)) {
  return [{
    json: {
      continuar: false,
      chat_id: datos.chat_id,
      mensaje: datos.mensaje,
    },
  }];
}

if (
  typeof datos.codigo_id !== 'string' ||
  !datos.codigo_id ||
  typeof datos.usuario_id !== 'string' ||
  !datos.usuario_id ||
  !/^[1-9]\d*$/.test(String(datos.chat_id))
) {
  throw new Error('Faltan identificadores para guardar la vinculación.');
}

const vencimiento = Date.parse(datos.expira_en);

if (!Number.isFinite(vencimiento)) {
  throw new Error('El vencimiento del código no es válido.');
}

if (vencimiento <= Date.now()) {
  return [{
    json: {
      continuar: false,
      chat_id: datos.chat_id,
      mensaje: 'El código venció. Solicita uno nuevo en EventPass.',
    },
  }];
}

const crear = datos.resultado === 'PERMITIDO';
const ahora = new Date().toISOString();

// Para una vinculación nueva, el identificador se deriva
// del registro del código que la originó.
const vinculacionId = crear
  ? `VIN-${datos.codigo_id}`
  : datos.vinculacion_id;

if (typeof vinculacionId !== 'string' || !vinculacionId) {
  throw new Error('Falta el identificador de la vinculación.');
}

return [{
  json: {
    continuar: true,
    crear_vinculacion: crear,
    codigo_id: datos.codigo_id,
    chat_id: datos.chat_id,

    vinculacion: {
      vinculacion_id: vinculacionId,
      usuario_id: datos.usuario_id,
      chat_id: datos.chat_id,
      telegram_username: datos.telegram_username ?? '',
      fecha_vinculacion: ahora,
      estado: 'ACTIVA',
    },
  },
}];
